package io.github.diodeme.ji.session.sqlite;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import io.github.diodeme.ji.ai.ModelRef;
import java.nio.file.Files;
import java.time.Instant;
import org.junit.jupiter.api.Test;

final class SqliteSessionRepositoryTest {
    @Test
    void persistsAcrossRepositoryRestartAndRejectsConcurrentStaleCas() throws Exception {
        var database = Files.createTempFile("ji-sqlite-reopen-", ".db");
        try (var first = new SqliteSessionRepository(database)) {
            first.create("session-1", new ModelRef("faux", "model"), "workspace", Instant.EPOCH);
            first.update("session-1", 0, document -> document.setName(java.util.Optional.of("Example")));
        }
        try (var first = new SqliteSessionRepository(database);
             var second = new SqliteSessionRepository(database)) {
            assertEquals("Example", first.load("session-1").orElseThrow().name().orElseThrow());
            first.update("session-1", 1, document -> document.setName(java.util.Optional.of("New")));
            assertThrows(IllegalStateException.class,
                    () -> second.update("session-1", 1, document -> document.setName(java.util.Optional.of("Stale"))));
            assertEquals("New", second.load("session-1").orElseThrow().name().orElseThrow());
        }
    }
}
